a11y.wcag.syntax:
/* WCAG Level AA compliant focus ring example */
button:focus-visible {
  outline: 3px solid #005f73;
  outline-offset: 2px;
}

a11y.keyboard-nav.syntax:
/* Ensuring visible focus styling */
button:focus-visible, a:focus-visible {
  outline: 3px solid #0056b3;
  outline-offset: 2px;
}

a11y.focus-visible.syntax:
button:focus {
  outline: none;
}
button:focus-visible {
  outline: 3px solid #005fcc;
  outline-offset: 2px;
}

