a11y.color-contrast.syntax:
/* CSS Example meeting 4.5:1 contrast */
.accessible-text {
  color: #FFFFFF; /* White */
  background-color: #000000; /* Black - Ratio 21:1 */
}

a11y.text-resize.syntax:
/* Responsive typography using relative rem units */
body {
  font-size: 1rem;
}
h1 {
  font-size: 2rem; /* Scales smoothly with browser zoom */
}

a11y.reduced-motion.syntax:
@media (prefers-reduced-motion: reduce) {
  selector {
    animation: none;
    transition: none;
  }
}

